API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Regional_API_Gateway, "Regional API Gateway", "Envoy", "Enables edge routing, WASM/Lua filters, and compression across europe-west3 and us-central1.")
    Component(WAF_Inspection, "WAF Inspection", "Google Cloud Armor", "Inspects incoming HTTPS traffic for security threats at the edge.")
    Component(Rate_Limiting_Store, "Rate Limiting Store", "Redis", "Distributed cache supporting rate limiting and quota controls.")
    Component(OpenTelemetry_Collectors, "OpenTelemetry Collectors", "OpenTelemetry", "Collects distributed traces and audit logs asynchronously.")
}

Rel(Regional_API_Gateway, WAF_Inspection, "Inspects traffic", "HTTPS")
Rel(Regional_API_Gateway, Rate_Limiting_Store, "Queries rate limits and quotas")
Rel(Regional_API_Gateway, OpenTelemetry_Collectors, "Sends telemetry and audit logs", "OTLP / gRPC, Async")

@enduml

LiveKit/WebRTC Media Relays.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the LiveKit/WebRTC Media Relays container

Container_Boundary(media_relays, "LiveKit/WebRTC Media Relays") {
    Component(TURN_STUN_Server, "TURN/STUN Server", "Coturn", "Provides NAT traversal and connection establishment for patients and clinicians.")
    Component(SFU_Media_Router, "SFU Media Router", "LiveKit (Go)", "Routes adaptive sub-300 kbit/s video streams for real-time telehealth consultations.")
    Component(Telemetry_Stats_Exporter, "Telemetry & Stats Exporter", "Prometheus exporter", "Emits network metrics and stream statistics for monitoring session quality.")
}

Rel(SFU_Media_Router, Telemetry_Stats_Exporter, "Emits network metrics", "Internal IPC / Prometheus scrape")

@enduml
